        {% endfor -%}
        {%- endmacro -%}
        '''), encoding="utf-8")

    (TEMPLATES_DIR / "readme.md.j2").write_text(textwrap.dedent('''\
        {%- from '_macros.j2' import render_summary_table, render_refs -%}
        {#- 主模版：散文从 prose[] 来（templates/prose/<key>.md），entries
            部分从 section_body[] 来（sections.body），层级标题从
            section_heading[] 来。-#}
        {{ prose.get('top', '') | trim }}
        {%- for lyr in layers %}

        ## {{ section_heading.get(lyr.code, lyr.code ~ ' ' ~ lyr.name) }}

        {% if lyr.code in prose %}{{ prose[lyr.code] | trim }}

        {% endif -%}
        {{ section_body.get(lyr.code, '') | trim }}
        {%- endfor %}

        {{ prose.get('parallel-intro', '') | trim }}
        {%- for br in branches if br.code != 'A' %}
        {%- if br.code in prose %}

        {{ prose[br.code] | trim }}
        {%- endif %}
        {%- for sub in sub_branches if sub.parent_code == br.code %}

        ### {{ section_heading.get(sub.code, sub.code ~ ' ' ~ sub.name) }}

        {% if sub.code in prose %}{{ prose[sub.code] | trim }}

        {% endif -%}
        {{ section_body.get(sub.code, '') | trim }}
        {%- endfor %}
        {%- endfor %}

        {{ prose.get('crosscut', '') | trim }}

        ## 参考文献

        {{ render_refs(refs) }}
        '''), encoding="utf-8")

    # summary-table + main-overview are emitted via prose files; insert them
    # in the right place by writing a wrapper into 'top' prose? Simpler: the
    # template just emits top, then summary-table prose, then main-overview
    # prose. Re-write template above to include those.

    print(f"wrote templates to {TEMPLATES_DIR}/")


def main():
    if not DB_PATH.exists():
        sys.exit(f"db not found: {DB_PATH}")
    conn = sqlite3.connect(DB_PATH)
    migrate(conn)
    emit_templates()
    conn.close()


if __name__ == "__main__":
